import type { Vec3 } from './math';
import type { Course, Hole } from '../courses/types';

export type PlayerId = string;
export type MatchId = string;
export type ControlScheme = 'drag-power' | 'hold-to-charge';
export type PlayerKind = 'human' | 'bot' | 'remote';
export type MatchPhase = 'lobby' | 'hole-intro' | 'aiming' | 'simulating' | 'hole-results' | 'match-results' | 'paused';

export interface PlayerProfile {
  id: PlayerId;
  displayName: string;
  kind: PlayerKind;
  ballStyleId: string;
  rating: number;
}

export interface PlayerHoleScore {
  playerId: PlayerId;
  holeId: string;
  strokes: number;
  completed: boolean;
  completionTimeMs?: number;
  penaltyStrokes: number;
}

export interface MatchPlayer extends PlayerProfile {
  connected: boolean;
  totalStrokes: number;
  holeScores: PlayerHoleScore[];
}

export interface MatchSettings {
  courseId: string;
  maxPlayers: number;
  strokeLimitPerHole: number;
  turnTimeLimitSeconds?: number;
}

export interface MatchDTO {
  id: MatchId;
  phase: MatchPhase;
  settings: MatchSettings;
  players: MatchPlayer[];
  currentHoleIndex: number;
  activePlayerId?: PlayerId;
  startedAt?: number;
  finishedAt?: number;
}

export interface ShotCommand {
  playerId: PlayerId;
  holeId: string;
  direction: Vec3;
  normalizedPower: number;
  clientSequence: number;
  issuedAt: number;
}

export interface GameSessionDTO {
  match: MatchDTO;
  course: Course;
  hole: Hole;
}
EOF
